t3template.addControl({ id: 'ticket', label: 'Ticket', type: 'text', default: 'WEB-142', placeholder: 'e.g. WEB-142', panel: 'Hand-off' });
t3template.addControl({ id: 'minText', label: 'Min Text px', type: 'slider', min: 10, max: 18, step: 1, default: 14, panel: 'Type Check' });
// Adds a low-priority change, with a font-size tweak, for each text smaller than Min Text px (up to 6 per run).
async function flagSmallText(t) {
  const root = t.page();
  if (!root) throw new Error('Flag Small Text needs an HTML snapshot');
  const min = t.getValues().controls.minText;
  const taken = new Set(t.getValues().changes.map((c) => c.selector).filter(Boolean));
  let added = 0;
  for (const node of root.querySelectorAll('p, li, a, span, small, cite')) {
    const px = parseFloat(getComputedStyle(node).fontSize);
    const selector = t.selectorOf(node);
    if (px >= min || !node.textContent.trim() || taken.has(selector)) continue;
    taken.add(selector);
    await t.addChange({ selector, note: `Text is ${px}px; raise it to at least ${min}px.`, priority: 'low', tweaks: { 'font-size': `${min}px` } });
    if (++added >= 6) break;
  }
  return added;
}
t3template.addToolbarButton('Flag Small Text', flagSmallText, { shortcut: 'shift+s', title: 'Add a change for each text smaller than Min Text px' });
// A fresh snapshot review starts with the type check already run.
if (t3template.page() && t3template.getValues().changes.length === 0) return flagSmallText(t3template);
